#include <bits/stdc++.h>
using namespace std;

struct Operation {
    int type, v, k;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> originalParent(N + 1, 1);
    vector<vector<int>> children(N + 1);

    for (int i = 2; i <= N; ++i) {
        cin >> originalParent[i];
        children[originalParent[i]].push_back(i);
    }

    int Q;
    cin >> Q;

    vector<Operation> operations(Q);
    for (auto &op : operations) {
        cin >> op.type >> op.v;
        if (op.type == 1) cin >> op.k;
    }

    vector<int> tin(N + 1), tout(N + 1);
    int timer = 0;
    vector<pair<int, int>> stack;
    stack.emplace_back(1, 0);
    tin[1] = ++timer;

    while (!stack.empty()) {
        int u = stack.back().first;
        int &nextChild = stack.back().second;

        if (nextChild < (int)children[u].size()) {
            int v = children[u][nextChild++];
            tin[v] = ++timer;
            stack.emplace_back(v, 0);
        } else {
            tout[u] = timer;
            stack.pop_back();
        }
    }

    const int LOG = 18;
    vector<vector<int>> up(LOG, vector<int>(N + 1));
    vector<int> lastOperation(N + 1, 0);
    vector<int> bestOperationAncestor(N + 1, 0);

    auto rebuild = [&]() {
        bestOperationAncestor[1] = 0;
        up[0][1] = 1;

        for (int v = 2; v <= N; ++v) {
            int p = originalParent[v];
            int best = bestOperationAncestor[p];

            up[0][v] = best ? best : p;
            bestOperationAncestor[v] = best;

            if (lastOperation[v] > lastOperation[bestOperationAncestor[v]]) {
                bestOperationAncestor[v] = v;
            }
        }

        for (int j = 1; j < LOG; ++j) {
            for (int v = 1; v <= N; ++v) {
                up[j][v] = up[j - 1][up[j - 1][v]];
            }
        }
    };

    auto jumpBaseline = [&](int v, int steps) {
        for (int j = 0; j < LOG; ++j) {
            if ((steps >> j) & 1) v = up[j][v];
        }
        return v;
    };

    rebuild();

    int blockSize = min(Q, max(1, (int)sqrt((double)N * LOG)));
    vector<int> active;
    vector<char> isActive(N + 1, false);
    vector<int> records;
    string output;

    for (int left = 0; left < Q; left += blockSize) {
        if (left > 0) rebuild();

        for (int v : active) isActive[v] = false;
        active.clear();

        int right = min(Q, left + blockSize);

        for (int i = left; i < right; ++i) {
            const auto &op = operations[i];

            if (op.type == 2) {
                int v = op.v;
                lastOperation[v] = i + 1;

                if (!isActive[v]) {
                    isActive[v] = true;
                    auto it = lower_bound(active.begin(), active.end(), tin[v],
                        [&](int node, int value) {
                            return tin[node] < value;
                        });
                    active.insert(it, v);
                }
            } else {
                records.clear();
                int maxTimestamp = 0;

                for (int a : active) {
                    if (a != op.v && tin[a] < tin[op.v] && tout[op.v] <= tout[a]) {
                        int timestamp = lastOperation[a];
                        if (timestamp > maxTimestamp) {
                            maxTimestamp = timestamp;
                            records.push_back(a);
                        }
                    }
                }

                int answer;
                if (op.k <= (int)records.size()) {
                    answer = records[records.size() - op.k];
                } else if (!records.empty()) {
                    answer = jumpBaseline(records.front(), op.k - (int)records.size());
                } else {
                    answer = jumpBaseline(op.v, op.k);
                }

                output += to_string(answer);
                output += '\n';
            }
        }
    }

    cout << output;
    return 0;
}
